package io.github.diodeme.ji.session;

import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.ai.Usage;
import java.util.List;
import java.util.Optional;

/** Canonical embedded Session storage port. Every write is revision-CAS protected. */
public interface SessionStore extends AutoCloseable {
    SessionSnapshot create(String sessionId, ModelRef model, String workingDirectory);
    Optional<SessionSnapshot> load(String sessionId);
    SessionSnapshot startRun(String sessionId, String runId, Message userMessage, long expectedRevision);
    SessionSnapshot append(String sessionId, String runId, List<Message> messages, Usage usage,
                           Optional<SessionSnapshot.ActiveRun> activeRun, long expectedRevision);

    @Override
    default void close() {}
}
